interface Window {
    rhombus: {
        deepslate: any;
        densityFunctions: Map<string, (obj: any, inputParser: any) => any>;
        visualizers: Map<string, any>;
        React: any;
        FastNoiseLite: any;
        pako: any;
    };
}

const { deepslate, densityFunctions, FastNoiseLite } = window.rhombus;

if (!deepslate.Registry.REGISTRY.has(deepslate.Identifier.parse("lithostitched:fast_noise_config"))) {
    const registry = new deepslate.Registry(deepslate.Identifier.parse("lithostitched:fast_noise_config"), (obj: any) => obj);
    deepslate.Registry.REGISTRY.register(registry.key, registry);
}

// --- 1. Sqrt ---
class LithostitchedSqrt extends deepslate.DensityFunction {
    input: any;
    constructor(input: any) { super(); this.input = input; }
    compute(context: any): number { return Math.sqrt(Math.max(0, this.input.compute(context))); }
    maxValue(): number { return Math.sqrt(Math.max(0, this.input.maxValue())); }
    minValue(): number { return Math.sqrt(Math.max(0, this.input.minValue())); }
    mapAll(visitor: any): any { return visitor.map(new LithostitchedSqrt(this.input.mapAll(visitor))); }
}
densityFunctions.set('lithostitched:sqrt', (obj: any, parser: any) => new LithostitchedSqrt(parser(obj.argument)));

// --- 2. Axis ---
class LithostitchedAxis extends deepslate.DensityFunction {
    axis: 'x' | 'y' | 'z';
    constructor(axis: 'x' | 'y' | 'z') { super(); this.axis = axis; }
    compute(context: any): number {
        if (this.axis === 'x') return context.x;
        if (this.axis === 'y') return context.y;
        return context.z;
    }
    minValue(): number { return this.axis === 'y' ? -4064 : -1e100; }
    maxValue(): number { return this.axis === 'y' ? 4064 : 1e100; }
    mapAll(visitor: any): any { return visitor.map(this); }
}
densityFunctions.set('lithostitched:axis', (obj: any) => new LithostitchedAxis(obj.axis));

